/**
 * SVG Exporter module
 * Handles exporting block data to SVG format
 */

const SVGExporter = (() => {
  const gridSize = 50;

  /**
   * Generate SVG from block data
   */
  function generateSVG(blockData) {
    const width = blockData.gridCols * gridSize;
    const height = blockData.gridRows * gridSize;

    let svg = `<?xml version="1.0" encoding="UTF-8"?>
<!-- Quilt Block -->
<!-- Generated by Quilt Block Planner -->
<!-- Grid: ${blockData.gridRows}x${blockData.gridCols} -->
<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
`;

    // Draw white background squares
    for (let row = 0; row < blockData.gridRows; row++) {
      for (let col = 0; col < blockData.gridCols; col++) {
        const x = col * gridSize;
        const y = row * gridSize;
        svg += `  <rect x="${x}" y="${y}" width="${gridSize}" height="${gridSize}" fill="#ffffff" stroke="none"/>\n`;
      }
    }

    // Draw colored squares
    if (blockData.squares && Array.isArray(blockData.squares)) {
      for (const square of blockData.squares) {
        const x = square.col * gridSize;
        const y = square.row * gridSize;
        const color = square.color || blockData.primaryColor || '#ff0000';
        svg += `  <rect x="${x}" y="${y}" width="${gridSize}" height="${gridSize}" fill="${color}" stroke="none"/>\n`;
      }
    }

    // Draw triangles
    if (blockData.triangles && Array.isArray(blockData.triangles)) {
      for (const triangle of blockData.triangles) {
        const color = triangle.color || blockData.secondaryColor || '#00ff00';
        const points = triangle.points.map(p => `${p[0]},${p[1]}`).join(' ');
        svg += `  <polygon points="${points}" fill="${color}" stroke="none"/>\n`;
      }
    }

    svg += `</svg>`;
    return svg;
  }

  /**
   * Export block as SVG file
   */
  function exportAsFile(blockData, filename = 'quilt-block.svg') {
    const svg = generateSVG(blockData);
    const blob = new Blob([svg], { type: 'image/svg+xml' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  }

  return {
    generateSVG,
    exportAsFile,
  };
})();
